}

/**
 * 放逐投票流水线：
 * 1) 在 onPreVote 窗口可触发狼人自爆中断。
 * 2) 存活且有投票权玩家依次投票，按权重计票。
 * 3) 调用 EventRegistry 处理白痴免死、警徽销毁等投后钩子。
 */
export class VotingPipeline {
  private static readonly MAX_VOTE_RETRIES = 3;
  private readonly world: World;
  private readonly selfDestructWindow: SelfDestructWindow;
  private readonly toolGateway: ToolGateway;
  private readonly eventRegistry: EventRegistry;
  private readonly events: GameEvent[];

  constructor(dependencies: VotingPipelineDependencies) {
    this.world = dependencies.world;
    this.toolGateway = dependencies.toolGateway;
    this.eventRegistry = dependencies.eventRegistry;
    this.events = dependencies.events;
    this.selfDestructWindow = new SelfDestructWindow(
      this.world,
      dependencies.roleRegistry,
      this.toolGateway,
    );
  }

  async execute(
    config: ReadonlyBoardConfig,
    actionProvider: ActionProvider,
    options: VotingPipelineOptions,
  ): Promise<VotingPipelineResult> {
    let unitDay: number;
    const requests = new GameActionRequestFactory(this.world, this.events, (unitDay = options.day));
    safeRecordLogicOp({
      scope: "phase_pipeline",
      op: "voting_pipeline_start",
      phase: Phase.Voting,
      status: "ok",
      input: {
        on_pre_vote_hook: config.hooks.onPreVote,
      },
    });
    if (config.hooks.onPreVote && isSelfDestructWindowEnabled(config, ActionWindow.OnPreVote)) {
      const exploded = await this.selfDestructWindow.execute(
        requests,
        actionProvider,
        ActionWindow.OnPreVote,
        Phase.Voting,
        options.isCurrent,
        options.commitSelfDestruct,
      );
      if (exploded !== null) {
        safeRecordLogicOp({
          scope: "phase_pipeline",
          op: "voting_interrupted_by_self_destruct",
          actorId: exploded.actorId,
          phase: Phase.Voting,
          status: "ok",
        });
        return {
          summary: {
            tally: {},
            target: null,
            removed:
              exploded.targetId === null
                ? [exploded.actorId]
                : [exploded.actorId, exploded.targetId],
          },
          interrupted: true,
          selfDestruct: exploded,
          removed:
            exploded.targetId === null ? [exploded.actorId] : [exploded.actorId, exploded.targetId],
        };
      }
    }

    if (options.isCurrent && !options.isCurrent())
      return { summary: { tally: {}, target: null, removed: [] }, interrupted: false, removed: [] };
    const animalUnit = config.animalDream
      ? beginAnimalExileUnit(
          this.world,
          (unitDay = options.day),
          "exile",
          () => options.isCurrent?.() !== false,
        )
      : undefined;
    // 此门禁已开启一次真实放逐；后续重新收票／PK仍消费同一个对象。
    const exileUnit = openExileUnit(unitDay, "exile", animalUnit);
    const voters = this.world
      .getAliveEntityIds()
      .filter((id) => canVoteExile(this.world, id, options.day));

    // 请求并行执行；Promise.all 保留原投票者顺序，公开票据按该顺序稳定发布。
    const voteResults = await this.collectVotes(voters, requests, actionProvider, options);
    if (options.isCurrent?.() === false)
      return attachExileUnit({ summary: { tally: {}, target: null, removed: [] }, interrupted: false, removed: [] }, exileUnit);
    let { tally, publicVotes } = this.recordVotesInSeatOrder(voteResults, options.day);
    if (animalUnit) recordAnimalBallotRound(this.world, animalUnit, 1, publicVotes);
    if (config.roleSetups.some((setup) => setup.role === Role.OrderPrince && setup.count > 0)) {
      const restarted = await runOrderPrinceChoice(
        this.world,
        requests,
        actionProvider,
        this.toolGateway,
        this.events,
        options.day,
        () => options.isCurrent?.() !== false,
      );
      if (restarted) {
        const previousCurrent = options.isCurrent;
        options = {
          ...options,
          strictRequired: true,
          orderPrinceRevote: true,
          isCurrent: () => {
            assertOrderPrinceOriginalCurrent(this.world);
            if (previousCurrent?.() === false) throw new Error("order_prince_revote_stale");
            return true;
          },
        };
        const freshVoters = this.world
          .getAliveEntityIds()
          .filter((id) => canVoteExile(this.world, id, options.day));
        const fresh = await this.collectVotes(freshVoters, requests, actionProvider, options);
        if (options.isCurrent?.() === false) throw new Error("order_prince_revote_stale");
        ({ tally, publicVotes } = this.recordVotesInSeatOrder(fresh, options.day, true));
      }
    }
    const pk = config.voting?.exilePolicy === "awa_one_pk_v1";
    const maximum = Math.max(
      0,
      ...Object.entries(tally)
        .filter(([id]) => canBeExiled(this.world, Number(id)))
        .map(([, score]) => score),
    );
    const tied =
      maximum > 0
        ? Object.entries(tally)
            .filter(([id, score]) => score === maximum && canBeExiled(this.world, Number(id)))
            .map(([id]) => Number(id))
        : [];
    let round = 1;
    if (pk && tied.length > 1) {
      this.events.push({
        timestamp: Date.now(),
        type: "vote_summary",
        payload: { votes: publicVotes, tally, target: null, round: 1 },
      });
      this.events.push({
        timestamp: Date.now(),
        type: "exile_pk_started",
        payload: { candidates: tied },
      });
      for (const actorId of tied) {
        if (options.isCurrent?.() === false)
          return attachExileUnit({
            summary: { tally: {}, target: null, removed: [] },
            interrupted: false,
            removed: [],
          }, exileUnit);
        const life = captureNightLife(this.world, actorId);
        if (!life || !canBeExiled(this.world, actorId)) {
          if (options.strictRequired) throw new Error("order_prince_pk_candidate_stale");
          continue;
        }
        const request = requests.create({
          phase: Phase.Voting,
          actorId,
          allowedTools: ["speak"],
          stage: "exile_pk_speech",
          requiresAction: true,
          summary: { key: "request.summary.exile_pk" },
          context: {
            exile_candidates: tied,
            round: 2,
            max_rounds: 2,
            ...(options.strictRequired
              ? { action_failure_policy: "error", allow_fallback: false }
              : {}),
          },
        });
        const action = await actionProvider.getAction(request);
        if (options.isCurrent?.() === false)
          return attachExileUnit({
            summary: { tally: {}, target: null, removed: [] },
            interrupted: false,
            removed: [],
          }, exileUnit);
        if (
          action?.name !== "speak" ||
          !livingNightLife(this.world, life) ||
          !canBeExiled(this.world, actorId)
        ) {
          if (options.strictRequired) throw new Error("order_prince_pk_speech_missing_or_stale");
          continue;
        }
        const result = this.toolGateway.validateAndSanitize(this.world, actorId, action, {
          phase: Phase.Voting,
          day: options.day,
        });
        if (
          options.strictRequired &&
          (!result.ok || !result.sanitizedCall || !livingNightLife(this.world, life))
        )
          throw new Error("order_prince_pk_speech_invalid");
        if (result.ok && result.sanitizedCall && livingNightLife(this.world, life))
          this.events.push({
            timestamp: Date.now(),
            type: "day_speech",
            payload: { actorId, text: result.sanitizedCall.args.text },
          });
      }
      const candidates = tied.filter((id) => canBeExiled(this.world, id));
      const revoters = this.world
        .getAliveEntityIds()
        .filter((id) => !tied.includes(id) && canVoteExile(this.world, id, options.day));
      const results = await this.collectVotes(
        revoters,
        requests,
        actionProvider,
        options,
        candidates,
      );
      if (options.isCurrent?.() === false)
        return attachExileUnit({
          summary: { tally: {}, target: null, removed: [] },
          interrupted: false,
          removed: [],
        }, exileUnit);
      ({ tally, publicVotes } = this.recordVotesInSeatOrder(
        results,
        options.day,
        options.strictRequired,
      ));
      round = 2;
      if (animalUnit) recordAnimalBallotRound(this.world, animalUnit, 2, publicVotes, candidates);
    }

    const target = this.pickMajorityTarget(
      Object.fromEntries(
        Object.entries(tally).filter(([id]) => canBeExiled(this.world, Number(id))),
      ),
      pk ? "no_elimination" : (config.tieBreaker?.exileVote ?? "min_id"),
    );
    this.events.push({
      timestamp: Date.now(),
      type: "vote_summary",
      payload: {
        votes: publicVotes,
        tally,
        target,
        ...(pk ? { round } : {}),
      },
    });
    safeRecordLogicOp({
      scope: "phase_pipeline",
      op: "vote_tally_resolved",
      phase: Phase.Voting,
      status: "ok",
      output: {
        tally,
        target,
      },
    });
    let animalRetaliation: readonly number[] = [];
    if (animalUnit) {
      sealAnimalBallots(this.world, animalUnit);
      animalRetaliation = await runAnimalPufferChoice(
        this.world,
        this.events,
        actionProvider,
        this.toolGateway,
        options.day,
        animalUnit,
        // 封存原票之后只提供惰性依赖；河豚在原有效 actor／scope 边界前独立构造，不能复用 requests。
        { get requestFactory() { return GameActionRequestFactory; } },
      );
    }
    if (target === null) {
      return attachExileUnit({
        summary: {
          tally,
          target: null,
          removed: [],
        },
        interrupted: false,
        removed: [],
        ...(animalUnit ? { animalUnit, animalRetaliation } : {}),
      }, exileUnit);
    }

    const mapped = config.trickster ? resolveTricksterExile(this.world, options.day, target) : null;
    if (mapped)
      this.events.push({ timestamp: Date.now(), type: "exile_target_mapped", payload: mapped });
    const effectiveTarget = mapped?.effectiveId ?? target;
    const thisPipeline = this;
    const reveal = revealSecretBodyExile(
      {
        get enabled() { return config.nobleSecretBody; },
        get world() { return thisPipeline.world; },
        get events() { return thisPipeline.events; },
        get requests() { return requests; },
        get toolGateway() { return thisPipeline.toolGateway; },
        get day() { return options.day; },
        get isCurrent() { return options.isCurrent; },
      },
      effectiveTarget,
    );
    const revealStep = reveal.next();
    if (!revealStep.done) {
      try {
        // 只等待原 Provider；未触发翻牌的同步完成路径不进入此处。
        const action = await actionProvider.getAction(revealStep.value);
        reveal.next(action);
      } finally {
        // Provider 同步抛错／拒绝时驱动本族关闭；已完成或抛错的生成器不会再次关闭 scope。
        reveal.return(false);
      }
      return attachExileUnit({ summary: { tally, target, removed: [] }, removed: [], interrupted: false }, exileUnit);
    }
    const votedOut = mapped?.missed
      ? { removed: [] }
      : this.eventRegistry.onVotedOut(this.world, effectiveTarget, this.events);
    const removed = [...votedOut.removed];

    if (removed.includes(effectiveTarget) && !animalUnit) {
      // 只有真正出局才广播 voted_out；白痴翻牌由事件总线单独广播。
      this.events.push({
        timestamp: Date.now(),
        type: "voted_out",
        payload: {
          target: effectiveTarget,
        },
      });
    }

    return attachExileUnit({
      summary: {
        tally,
        target,
        ...(mapped ? { effectiveTarget: mapped.missed ? null : effectiveTarget } : {}),
        removed,
      },
      interrupted: false,
      removed,
      ...(animalUnit ? { animalUnit, animalRetaliation } : {}),
    }, exileUnit);
  }

  private async collectVotes(
    voters: EntityId[],
    requests: GameActionRequestFactory,
    actionProvider: ActionProvider,
    options: VotingPipelineOptions,
    candidates?: EntityId[],
  ): Promise<Array<CollectedVote | null>> {
    // 在调用任何 Provider 之前捕获完整轮次；同步测试 Provider 也不能改变后续捕获的原生命。
    const voterLives = voters.map((voterId) => ({
      voterId,
      life: captureNightLife(this.world, voterId),
    }));
    const targetLives = new Map(
      (candidates ?? this.world.getAliveEntityIds()).flatMap((id) => {
        const life = captureNightLife(this.world, id);
        return life ? [[id, life] as const] : [];
      }),
    );
    return Promise.all(
      voterLives.map(({ voterId, life }) =>
        life
          ? this.collectVoterVote(
              voterId,
              life,
              targetLives,
              requests,
              actionProvider,
              options,
              candidates,
            )
          : null,
      ),
    );
  }

  private async collectVoterVote(
    voterId: EntityId,
    voterLife: NonNullable<ReturnType<typeof captureNightLife>>,
    targetLives: ReadonlyMap<EntityId, NonNullable<ReturnType<typeof captureNightLife>>>,
    requests: GameActionRequestFactory,
    actionProvider: ActionProvider,
    options: VotingPipelineOptions,
    candidates?: EntityId[],
  ): Promise<CollectedVote | null> {
    const current = () => {
      const valid =
        options.isCurrent?.() !== false &&
        livingNightLife(this.world, voterLife) &&
        canVoteExile(this.world, voterId, options.day) &&
        !candidates?.includes(voterId);
      if (!valid && options.strictRequired) throw new Error("order_prince_revote_actor_stale");
      return valid;
    };
    const maxRetries = VotingPipeline.MAX_VOTE_RETRIES;
    let retryReason = "";
    const recordRetry = (attempt: number) =>
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "vote_retry_requested",
        actorId: voterId,
        phase: Phase.Voting,
        status: "fallback",
        reason: retryReason,
        output: { attempt, max_retries: maxRetries },
      });

    for (let attempt = 1; attempt <= maxRetries + 1; attempt++) {
      if (!current()) return null;
      const baseRequest = requests.create({
        phase: Phase.Voting,
        actorId: voterId,
        allowedTools: ["vote"],
        stage: candidates
          ? "exile_pk_vote"
          : options.orderPrinceRevote
            ? "order_prince_revote"
            : "voting",
        requiresAction: true,
        summary: { key: "request.summary.exile_vote" },
        context: {
          ...(candidates ? { exile_candidates: candidates, round: 2, max_rounds: 2 } : {}),
          ...(options.strictRequired
            ? { action_failure_policy: "error", allow_fallback: false }
            : {}),
        },
      });
      const request =
        attempt === 1
          ? baseRequest
          : {
              ...baseRequest,
              context: {
                ...baseRequest.context,
                retry_attempt: attempt - 1,
                retry_max: maxRetries,
                retry_reason: retryReason,
                retry_notice_message: { key: "request.retry.exile_vote" as const },
              },
            };
      if (!current()) return null;
      const action = await actionProvider.getAction(request);
      if (!current()) return null;
      if (action?.name !== "vote") {
        retryReason = "no_valid_vote_tool_call";
        if (attempt <= maxRetries) {
          recordRetry(attempt);
          continue;
        }
        break;
      }

      const result = this.toolGateway.validateAndSanitize(this.world, voterId, action, {
        phase: Phase.Voting,
        day: options.day,
        exileCandidates: candidates,
      });
      if (
        !result.ok ||
        !result.sanitizedCall ||
        (!result.sanitizedCall.args.abstain &&
          (!targetLives.get(result.sanitizedCall.args.target_id!) ||
            !livingNightLife(this.world, targetLives.get(result.sanitizedCall.args.target_id!)!)))
      ) {
        retryReason = "invalid_vote_arguments";
        if (attempt <= maxRetries) {
          recordRetry(attempt);
          continue;
        }
        break;
      }
      return {
        voterId,
        targetId: result.sanitizedCall.args.target_id,
        abstain: result.sanitizedCall.args.abstain === true,
        fallback: attempt > 1,
        voterLife,
        ...(result.sanitizedCall.args.target_id !== null
          ? { targetLife: targetLives.get(result.sanitizedCall.args.target_id) }
          : {}),
      };
    }

    if (!current()) return null;
    if (options.strictRequired) throw new Error("order_prince_revote_action_missing_or_invalid");
    // 重试耗尽后仍需原网关接受，才将缺失行动修复为明确弃票。
    const repaired = this.toolGateway.validateAndSanitize(
      this.world,
      voterId,
      { name: "vote", args: { target_id: null, abstain: true } },
      { phase: Phase.Voting, day: options.day, exileCandidates: candidates },
    );
    if (repaired.ok && repaired.sanitizedCall) {
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "vote_repaired_to_abstain",
        actorId: voterId,
        phase: Phase.Voting,
        status: "ok",
        reason: retryReason || "vote_retry_exhausted",
      });
      return { voterId, targetId: null, abstain: true, fallback: true, voterLife };
    }
    safeRecordLogicOp({
      scope: "phase_pipeline",
      op: "vote_rejected",
      actorId: voterId,
      phase: Phase.Voting,
      status: "rejected",
      reason: retryReason || "vote_retry_exhausted",
    });
    return null;
  }

  private recordVotesInSeatOrder(
    votes: Array<CollectedVote | null>,
    day: number,
    strictRequired = false,
  ): {
    tally: Record<number, number>;
    publicVotes: VoteRecord[];
  } {
    const tally: Record<number, number> = {};
    const publicVotes: VoteRecord[] = [];
    for (const vote of votes) {
      if (!vote) continue;
      const { voterId } = vote;
      if (
        !livingNightLife(this.world, vote.voterLife) ||
        (!vote.abstain && (!vote.targetLife || !livingNightLife(this.world, vote.targetLife))) ||
        !canVoteExile(this.world, voterId, day) ||
        (!vote.abstain && vote.targetId !== null && !canBeExiled(this.world, vote.targetId))
      ) {
        if (strictRequired) throw new Error("order_prince_revote_ballot_stale");
        continue;
      }
      let weight = 0;
      if (!vote.abstain && vote.targetId !== null) {
        const voting = this.world.getComponent(voterId, COMPONENT.VotingRight);
        weight = voting?.weight ?? 1;
        tally[vote.targetId] = (tally[vote.targetId] ?? 0) + weight;
      }
      this.events.push({
        timestamp: Date.now(),
        type: "vote_cast",
        payload: {
          actorId: voterId,
          targetId: vote.targetId,
          abstain: vote.abstain,
          weight,
          ...(vote.fallback ? { fallback: true } : {}),
        },
      });
      publicVotes.push({
        actorId: voterId,
        targetId: vote.targetId,
        abstain: vote.abstain,
        weight,
      });
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "vote_cast",
        actorId: voterId,
        phase: Phase.Voting,
        status: "ok",
        output: { target_id: vote.targetId, abstain: vote.abstain, weight },
      });
    }
    return { tally, publicVotes };
  }

  /**
   * 依据计票结果选出放逐目标，平票按编号最小值决议。
   */
  private pickMajorityTarget(
    tally: Record<number, number>,
    strategy: TieBreakerStrategy,
  ): EntityId | null {
    const entries = Object.entries(tally);
    if (entries.length === 0) {
      return null;
    }

    entries.sort((a, b) => {
      const voteDiff = b[1] - a[1];
      if (voteDiff !== 0) {
        return voteDiff;
      }
      if (strategy === "min_seat") {
        const aId = Number(a[0]);
        const bId = Number(b[0]);
        const aSeat = this.world.getComponent(aId, COMPONENT.Identity)?.seat ?? aId;
        const bSeat = this.world.getComponent(bId, COMPONENT.Identity)?.seat ?? bId;
        return aSeat - bSeat;
      }
      return Number(a[0]) - Number(b[0]);
    });

    if (entries.length >= 2 && entries[0][1] === entries[1][1]) {
      if (strategy === "no_elimination") {
        return null;
      }
    }

    return Number(entries[0][0]);
  }
}

/**
 * 负责狼美人魅惑绑定、领取／阻断／实际死亡回执和放逐胜利边界。
 * 输入为原源／目标引用及死亡原因；输出为仍当前的关系和具体阶段结果，bindings 是唯一权威状态。
 * resolved 表示牵连已经领取，applied 表示目标确实死亡；梦阻断仍消耗领取，不能退款重触发。
 * 回执只保同一绑定的不可伪造运行时引用，不复制状态或授予死亡权限；不标死或发布事实。
 * 规则来源：docs/rules/awa-wolf-beauty-v1.md，各政策保留其独立来源抑制。
 */
import type { WolfBeautyReadState as WolfBeautyState } from "@ai-werewolf-arena/game-contract";

import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import {
  Role,
  Camp,
  DeathCause,
  type DeathSources,
  type EntityId,
  type WinDecision,
} from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { getWolfBeautyState } from "./state";
import { getDefaultRoleCatalog } from "../role-catalog-assembly";
import { victoryDecision } from "../../win_conditions/results";

export interface CharmBinding {
  readonly actorId: EntityId;
  readonly targetId: EntityId;
  readonly role: Readonly<RoleComponent>;
  readonly state: WolfBeautyState;
  readonly actorLife: Readonly<AliveComponent>;
  readonly actorVersion: number | undefined;
  readonly targetLife: Readonly<AliveComponent>;
  readonly targetVersion: number | undefined;
  readonly resolved: boolean;
  readonly applied: boolean;
  readonly deathLinkPolicy: import("../../../../core/domain/board").BeautyDeathLinkPolicy;
}
const bindings = new WeakMap<World, Map<EntityId, CharmBinding>>();

// 回执只是本次触发的阶段结果；关系库存／原体资格始终由上面的单一 bindings 持有。
// 私有 Symbol 不进入 JSON，WeakSet 只标记身份，不保存第二份关系或 World 状态。
const RECEIPT_BRAND = Symbol("charm_receipt_brand");
const RECEIPT_BINDING = Symbol("charm_receipt_binding");
const issuedReceipts = new WeakSet<object>();
type CharmReceipt<K extends "claimed" | "blocked" | "applied"> = Readonly<{
  kind: K;
  [RECEIPT_BRAND]: true;
}>;
export type CharmClaimReceipt = CharmReceipt<"claimed">;
export type CharmBlockedReceipt = CharmReceipt<"blocked">;
export type CharmAppliedReceipt = CharmReceipt<"applied">;
export type CharmProtectionReceipt = CharmClaimReceipt | CharmBlockedReceipt;

function issueReceipt<K extends CharmProtectionReceipt["kind"] | "applied">(
  kind: K,
  binding: CharmBinding,
): CharmReceipt<K> {
  const receipt: CharmReceipt<K> = { kind, [RECEIPT_BRAND]: true };
  Object.defineProperty(receipt, RECEIPT_BINDING, { value: binding });
  issuedReceipts.add(receipt);
  return Object.freeze(receipt);
}
export function bindCharm(world: World, actorId: EntityId, targetId: EntityId | null): void {
  const map = bindings.get(world) ?? new Map<EntityId, CharmBinding>();
  bindings.set(world, map);
  map.delete(actorId);
  if (targetId === null) return;
  const role = world.getComponent(actorId, COMPONENT.Role)!,
    state = getWolfBeautyState(role)!,
    actorLife = world.getComponent(actorId, COMPONENT.Alive)!,
    targetLife = world.getComponent(targetId, COMPONENT.Alive)!;
  map.set(actorId, {
    actorId,
    targetId,
    role,
    state,
    actorLife,
    actorVersion: aliveLifeVersion(actorLife),
    targetLife,
    targetVersion: aliveLifeVersion(targetLife),
    resolved: false,
    applied: false,
    deathLinkPolicy: state.deathLinkPolicy ?? "awa_exile_poison_v1",
  });
}
function current(world: World, binding: CharmBinding): boolean {
  return (
    world.getComponent(binding.actorId, COMPONENT.Role) === binding.role &&
    binding.role.role === Role.WolfBeauty &&
    getWolfBeautyState(binding.role) === binding.state &&
    binding.state.targetId === binding.targetId &&
    (binding.state.deathLinkPolicy ?? "awa_exile_poison_v1") === binding.deathLinkPolicy &&
    world.getComponent(binding.actorId, COMPONENT.Alive) === binding.actorLife &&
    binding.actorVersion !== undefined &&
    aliveLifeVersion(binding.actorLife) ===
      binding.actorVersion + (binding.actorLife.alive ? 0 : 1) &&
    world.getComponent(binding.targetId, COMPONENT.Alive) === binding.targetLife &&
    binding.targetVersion !== undefined &&
    aliveLifeVersion(binding.targetLife) ===
      binding.targetVersion + (binding.targetLife.alive ? 0 : 1)
  );
}
export function activeCharm(world: World, actorId: EntityId): CharmBinding | null {
  const binding = bindings.get(world)?.get(actorId);
  return binding && !binding.resolved && current(world, binding) ? binding : null;
}
/** 在追加死因或标死之前同步领取；同波原体允许首次死亡版本，不接受复活或替身。 */
function claimCharm(
  world: World,
  binding: CharmBinding,
  eligibleDead: ReadonlySet<EntityId>,
): boolean {
  if (
    activeCharm(world, binding.actorId) !== binding ||
    binding.actorLife.alive ||
    (!binding.targetLife.alive && !eligibleDead.has(binding.targetId))
  )
    return false;
  (binding as { resolved: boolean }).resolved = true;
  return true;
}
/**
 * 具体触发流程拥有来源政策→原体领取→夜梦阻断分类；World 与保护查询都延迟到原表达式位置。
 * 不提前获取 World，permit 不合格时也不读保护；阻断／查询抛错仍保已经 resolved 的原付款。
 */
export function attemptCharmTrigger(
  binding: CharmBinding,
  sources: DeathSources,
  nativeHunterShotTargets: ReadonlySet<EntityId>,
  eligibleDead: ReadonlySet<EntityId>,
  world: () => World,
  blocksNightCharm: () => unknown,
): CharmProtectionReceipt | null {
  if (
    !permitsCharm(
      sources[binding.actorId] ?? [],
      binding.deathLinkPolicy,
      nativeHunterShotTargets.has(binding.actorId),
    ) ||
    !claimCharm(world(), binding, eligibleDead)
  )
    return null;
  return issueReceipt(blocksNightCharm() ? "blocked" : "claimed", binding);
}

/** 实际目标标死之后提交 applied；回执不能替代原同绑定、角色、政策及生命版本检查。 */
export function commitCharmDeath(
  world: World,
  receipt: CharmClaimReceipt,
): CharmAppliedReceipt | null {
  if (!issuedReceipts.has(receipt) || receipt.kind !== "claimed") return null;
  const binding = (receipt as CharmClaimReceipt & { readonly [RECEIPT_BINDING]: CharmBinding })[
    RECEIPT_BINDING
  ];
  if (
    bindings.get(world)?.get(binding.actorId) !== binding ||
    !binding.resolved ||
    !current(world, binding) ||
    binding.targetLife.alive
  )
    return null;
  (binding as { applied: boolean }).applied = true;
  return issueReceipt("applied", binding);
}
export interface BeautyExileCandidate {
  actorId: EntityId;
  targetId: EntityId;
  side: "god" | "villager";
  binding: CharmBinding;
}
/** 仅在真实放逐已确定、完整死亡波尚未执行时捕获候选，不提前封盘。 */
export function captureBeautyExile(world: World, actorId: EntityId): BeautyExileCandidate | null {
  const actor = world.getComponent(actorId, COMPONENT.Role),
    binding = activeCharm(world, actorId);
  if (
    actor?.role !== Role.WolfBeauty ||
    actor.camp !== Camp.Wolf ||
    !binding ||
    !binding.targetLife.alive
  )
    return null;
  if (
    world
      .getAliveEntityIds()
      .some((id) => id !== actorId && world.getComponent(id, COMPONENT.Role)?.camp === Camp.Wolf)
  )
    return null;
  const target = world.getComponent(binding.targetId, COMPONENT.Role),
    side = target ? getDefaultRoleCatalog().metadata(target.role)?.goodSide : undefined;
  return target?.camp === Camp.Good && side
    ? { actorId, targetId: binding.targetId, side, binding }
    : null;
}
export function resolveBeautyExileVictory(
  world: World,
  candidate: BeautyExileCandidate | null,
): WinDecision | null {
  if (
    !candidate ||
    !candidate.binding.applied ||
    !current(world, candidate.binding) ||
    candidate.binding.targetLife.alive
  )
    return null;
  const sideAlive = world.getAliveEntityIds().some((id) => {
    const role = world.getComponent(id, COMPONENT.Role);
    return (
      role?.camp === Camp.Good &&
      getDefaultRoleCatalog().metadata(role.role)?.goodSide === candidate.side
    );
  });
  return sideAlive
    ? null
    : victoryDecision(world, { kind: "faction", faction: Camp.Wolf }, "wolf_beauty_last_exile");
}
export function permitsCharm(
  sources: readonly DeathCause[],
  policy: import("../../../../core/domain/board").BeautyDeathLinkPolicy = "awa_exile_poison_v1",
  nativeHunterShot = false,
): boolean {
  // S7 仅规定放逐／原生猎人；未定义的复合死因先按抑制处理，不把赠枪当原生枪。
  if (policy === "heroes_s7_2017_exile_hunter_v1")
    return (
      sources.length > 0 &&
      sources.every(
        (source) => source === DeathCause.Exile || (source === DeathCause.Shot && nativeHunterShot),
      )
    );
  if (policy !== "awa_exile_poison_v1") return false;
  return (
    !sources.includes(DeathCause.Lovers) &&
    !sources.includes(DeathCause.Duel) &&
    !sources.includes(DeathCause.Dream) &&
    sources.some((source) => source === DeathCause.Exile || source === DeathCause.Poison)
  );
}
